public class PalindromeSearchTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("longest palindrome wins", java.util.Optional.of("level"),
                PalindromeSearch.longestPalindromicWord(java.util.List.of("Anna", "level", "stone")));

        check("tie goes to the first in list order", java.util.Optional.of("noon"),
                PalindromeSearch.longestPalindromicWord(java.util.List.of("noon", "abba", "deed")));

        check("case-insensitive check keeps original word", java.util.Optional.of("Racecar"),
                PalindromeSearch.longestPalindromicWord(java.util.List.of("stone", "Racecar", "pop")));

        check("later longer palindrome beats earlier shorter one", java.util.Optional.of("redivider"),
                PalindromeSearch.longestPalindromicWord(java.util.List.of("pop", "redivider", "noon")));

        check("single letters never qualify", java.util.Optional.empty(),
                PalindromeSearch.longestPalindromicWord(java.util.List.of("z", "hello", "x")));

        check("two-letter palindrome qualifies", java.util.Optional.of("aa"),
                PalindromeSearch.longestPalindromicWord(java.util.List.of("ab", "aa", "cd")));

        check("no palindromes at all", java.util.Optional.empty(),
                PalindromeSearch.longestPalindromicWord(java.util.List.of("stone", "brick", "cloud")));

        check("empty input list", java.util.Optional.empty(),
                PalindromeSearch.longestPalindromicWord(java.util.List.of()));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

