public class PalindromeSearch {

    private static boolean isPalindrome(String word) {
        String lower = word.toLowerCase(java.util.Locale.US);
        return new StringBuilder(lower).reverse().toString().equals(lower);
    }

    public static java.util.Optional<String> longestPalindromicWord(java.util.List<String> words) {
        return words.stream()
                .filter(w -> w.length() >= 2)
                .filter(PalindromeSearch::isPalindrome)
                .reduce((best, next) -> next.length() > best.length() ? next : best);
    }
}
